var t=`0694-amiwo`;var n=`world-0694`;var s=`BJ`;var o=`western-africa`;var a=4;var r=40;var l={en:`Amiwo`,ua:`Аміво`};var g={en:`Amiwo is a Benin classic prepared with yellow onion, tomato, cornmeal, fish (unspecified). A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Аміво, страва кухні країни Бенін зі складниками: жовта цибуля, помідор, кукурудзяна крупа дрібного помелу, риба (невизначений вид). Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var m=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,140,`g`],[`tomato`,420,`g`],[`red-palm-oil`,60,`ml`],[`hot-paprika`,6,`g`]]},{en:`Slowly stir the grains into the simmering liquid; cook over low heat for about 24 minutes, stirring to prevent sticking.`,ua:`Повільно всипте крупу в гарячу рідину; варіть на слабкому вогні приблизно 24 хвилин, помішуючи, щоб не пристала до дна.`,t:[`absorption-cooking`],m:24,i:[[`cornmeal`,350,`g`],[`water`,900,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`fish-unspecified`,250,`g`],[`table-salt`,null,`to_taste`]]}];var d={slug:t,id:n,country:`BJ`,region:o,servings:4,minutes:40,title:l,text:g,steps:m};export{s as country,d as default,n as id,r as minutes,o as region,a as servings,t as slug,m as steps,g as text,l as title};